const table=Array.from({length:256},(_,n)=>{let c=n;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;return c>>>0;});
export function crc32(bytes){let c=0xffffffff;for(const n of bytes)c=(c>>>8)^table[(c^n)&255];return (c^0xffffffff)>>>0;}
export function studioZip(files){if(files.length>102)throw Error('Too many files for one project package.');const enc=new TextEncoder(),local=[],central=[];let offset=0,centralSize=0,total=0;for(const file of files){if(!file.name||file.name.includes('..')||file.name.startsWith('/')||file.name.includes('\\'))throw Error('Invalid package filename.');const name=enc.encode(file.name),data=file.data instanceof Uint8Array?file.data:enc.encode(file.data);total+=data.length;if(total>100*1048576)throw Error('Package exceeds 100 MB. Download the brief separately or use fewer attached files.');const crc=crc32(data),head=new Uint8Array(30+name.length),h=new DataView(head.buffer);h.setUint32(0,0x04034b50,true);h.setUint16(4,20,true);h.setUint16(6,0x800,true);h.setUint16(12,33,true);h.setUint32(14,crc,true);h.setUint32(18,data.length,true);h.setUint32(22,data.length,true);h.setUint16(26,name.length,true);head.set(name,30);local.push(head,data);const entry=new Uint8Array(46+name.length),e=new DataView(entry.buffer);e.setUint32(0,0x02014b50,true);e.setUint16(4,20,true);e.setUint16(6,20,true);e.setUint16(8,0x800,true);e.setUint16(14,33,true);e.setUint32(16,crc,true);e.setUint32(20,data.length,true);e.setUint32(24,data.length,true);e.setUint16(28,name.length,true);e.setUint32(42,offset,true);entry.set(name,46);central.push(entry);centralSize+=entry.length;offset+=head.length+data.length;}const end=new Uint8Array(22),view=new DataView(end.buffer);view.setUint32(0,0x06054b50,true);view.setUint16(8,files.length,true);view.setUint16(10,files.length,true);view.setUint32(12,centralSize,true);view.setUint32(16,offset,true);return new Blob([...local,...central,end],{type:'application/zip'});}
